SELECT 'sentry' AS k, entity_index, max("m_iTeamNum") AS team, max("m_iMaxHealth") AS hp, min("CBodyComponent__m_cellX") AS cx, min("CBodyComponent__m_cellY") AS cy, min("CBodyComponent__m_vecX") AS vx, min("CBodyComponent__m_vecY") AS vy, min(tick) AS t0, max(tick) AS t1, CAST(NULL AS VARCHAR) AS phase FROM CNPC_BaseDefenseSentry GROUP BY entity_index
UNION ALL SELECT 'shielded', entity_index, max("m_iTeamNum"), max("m_iMaxHealth"), min("CBodyComponent__m_cellX"), min("CBodyComponent__m_cellY"), min("CBodyComponent__m_vecX"), min("CBodyComponent__m_vecY"), min(tick), max(tick), NULL FROM CNPC_ShieldedSentry GROUP BY entity_index
UNION ALL SELECT 'core', entity_index, max("m_iTeamNum"), max("m_iMaxHealth"), min("CBodyComponent__m_cellX"), min("CBodyComponent__m_cellY"), min("CBodyComponent__m_vecX"), min("CBodyComponent__m_vecY"), min(tick), max(tick), NULL FROM CNPC_Boss_Tier3Core GROUP BY entity_index
UNION ALL SELECT 'phase', entity_index, max("m_iTeamNum"), NULL, NULL, NULL, NULL, NULL, min(tick), max(tick), CAST("m_ePhase" AS VARCHAR) FROM CNPC_Boss_Tier3 GROUP BY entity_index, CAST("m_ePhase" AS VARCHAR)
